 static void ClearRoot(UIElement root){var panel=root as Panel;if(panel!=null)panel.Background=Brushes.Transparent;var border=root as Border;if(border!=null)border.Background=Brushes.Transparent;}
 static void ToggleMax(Window w){w.WindowState=w.WindowState==WindowState.Maximized?WindowState.Normal:WindowState.Maximized;}
 static bool Interactive(DependencyObject node,DependencyObject limit){while(node!=null&&node!=limit){if(node is ButtonBase||node is TextBoxBase||node is ComboBox||node is ScrollBar||node is ICSharpCode.AvalonEdit.TextEditor)return true;node=VisualTreeHelper.GetParent(node);}return false;}
 static Button ChromeButton(string title,string data){var b=Theme.Button("");b.Width=34;b.Height=32;b.MinHeight=32;b.Padding=new Thickness(0);b.Margin=new Thickness(0,0,4,0);b.Background=Brushes.Transparent;b.BorderThickness=new Thickness(0);var path=new Path{Data=Geometry.Parse(data),StrokeThickness=1.35,Width=18,Height=18,Stretch=Stretch.None,HorizontalAlignment=HorizontalAlignment.Center,VerticalAlignment=VerticalAlignment.Center};path.SetBinding(Shape.StrokeProperty,new System.Windows.Data.Binding("Foreground"){Source=b});b.Content=path;Name(b,title);return b;}
 static void Name(Button b,string title){b.ToolTip=title;ToolTipService.SetInitialShowDelay(b,300);ToolTipService.SetShowOnDisabled(b,true);AutomationProperties.SetName(b,title);}
 public static void PrepareTree(DependencyObject node,Window window,bool dark){if(node==null)return;var border=node as Border;if(border!=null&&border.CornerRadius.TopLeft>0)border.CornerRadius=new CornerRadius(Math.Max(16,border.CornerRadius.TopLeft));var button=node as Button;if(button!=null)Iconize(button);var text=node as TextBlock;if(text!=null)Scope(node,TextBlock.ForegroundProperty,window,dark);var control=node as Control;if(control!=null){Scope(node,Control.ForegroundProperty,window,dark);Scope(node,Control.BackgroundProperty,window,dark);Scope(node,Control.BorderBrushProperty,window,dark);}var panel=node as Panel;if(panel!=null)Scope(node,Panel.BackgroundProperty,window,dark);if(border!=null){Scope(node,Border.BackgroundProperty,window,dark);Scope(node,Border.BorderBrushProperty,window,dark);}
  int count=VisualTreeHelper.GetChildrenCount(node);for(int i=0;i<count;i++)PrepareTree(VisualTreeHelper.GetChild(node,i),window,dark);
 }
 static void Scope(DependencyObject node,DependencyProperty property,Window window,bool dark){if(!dark)return;var brush=node.GetValue(property) as Brush;string key=GlassTheme.Key(brush);if(key==null)return;var element=node as FrameworkElement;if(element!=null)element.SetResourceReference(property,"Glass"+key);}
