 static void Iconize(Button button){var label=button.Content as string;if(label==null)return;string path;if(!icons.TryGetValue(label,out path))return;string tip=button.ToolTip as string;if(string.IsNullOrEmpty(tip))tip=label;var icon=new Path{Data=Geometry.Parse(path),StrokeThickness=1.45,StrokeStartLineCap=PenLineCap.Round,StrokeEndLineCap=PenLineCap.Round,StrokeLineJoin=PenLineJoin.Round,Stretch=Stretch.Uniform,Width=18,Height=18,IsHitTestVisible=false};icon.SetBinding(Shape.StrokeProperty,new System.Windows.Data.Binding("Foreground"){Source=button});button.Content=icon;button.Width=36;button.Height=32;button.MinHeight=32;button.Padding=new Thickness(6,4,6,4);button.Margin=new Thickness(3,0,3,0);Name(button,tip);button.Tag=button.Tag??("icon:"+label);}
