 public static bool CornersAligned(Window w){State state;if(!states.TryGetValue(w,out state)||state.Frame==null)return false;var clip=state.Frame.Clip as RectangleGeometry;if(clip==null||Math.Abs(clip.Rect.Width-state.Frame.ActualWidth)>.01||Math.Abs(clip.Rect.Height-state.Frame.ActualHeight)>.01||clip.RadiusX!=state.Frame.CornerRadius.TopLeft)return false;var handle=new WindowInteropHelper(w).Handle;RECT bounds;if(!GetWindowRect(handle,out bounds))return false;var region=CreateRectRgn(0,0,0,0);try{return GetWindowRgn(handle,region)>0&&!PtInRegion(region,0,0)&&PtInRegion(region,(bounds.right-bounds.left)/2,(bounds.bottom-bounds.top)/2);}finally{DeleteObject(region);}}
 static void AlignNativeRegion(Window window,HwndSource source,double radius){if(source==null||source.IsDisposed||window.WindowState==WindowState.Minimized)return;var handle=new WindowInteropHelper(window).Handle;if(radius==0){SetWindowRgn(handle,IntPtr.Zero,true);return;}RECT rect;if(!GetWindowRect(handle,out rect))return;double dpi=source.CompositionTarget.TransformToDevice.M11;int diameter=(int)Math.Round(radius*2*dpi);var region=CreateRoundRectRgn(0,0,rect.right-rect.left+1,rect.bottom-rect.top+1,diameter,diameter);if(region!=IntPtr.Zero&&SetWindowRgn(handle,region,true)==0)DeleteObject(region);}
 static IntPtr MaxBounds(IntPtr hwnd,int message,IntPtr wparam,IntPtr lparam,ref bool handled){if(message!=0x24)return IntPtr.Zero;var info=new MONITORINFO{cbSize=Marshal.SizeOf(typeof(MONITORINFO))};if(GetMonitorInfo(MonitorFromWindow(hwnd,2),ref info)){var mm=(MINMAXINFO)Marshal.PtrToStructure(lparam,typeof(MINMAXINFO));mm.maxPosition.x=info.work.left-info.monitor.left;mm.maxPosition.y=info.work.top-info.monitor.top;mm.maxSize.x=info.work.right-info.work.left;mm.maxSize.y=info.work.bottom-info.work.top;Marshal.StructureToPtr(mm,lparam,false);handled=true;}return IntPtr.Zero;}
